-- Glossary Library. Run ONE statement at a time in D1 Studio.
CREATE TABLE IF NOT EXISTS glossary_terms (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL UNIQUE, term TEXT NOT NULL, category_slug TEXT NOT NULL DEFAULT '', short_definition TEXT NOT NULL DEFAULT '', content TEXT NOT NULL DEFAULT '', why_it_matters TEXT NOT NULL DEFAULT '', example TEXT NOT NULL DEFAULT '', related_terms TEXT NOT NULL DEFAULT '', related_guides TEXT NOT NULL DEFAULT '', related_products TEXT NOT NULL DEFAULT '', seo_title TEXT NOT NULL DEFAULT '', meta_description TEXT NOT NULL DEFAULT '', keywords TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'draft', featured INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()), published_at INTEGER);
CREATE TABLE IF NOT EXISTS glossary_categories (slug TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', sort_order INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS glossary_terms_status_idx ON glossary_terms (status, category_slug);
